function renderCalendarDetail(day){const box=$('calendarDetail'),d=store.days[day],e=d?C.energy(store,day):null;box.innerHTML='<h2>'+esc(day)+' の記録</h2>';if(!d)box.innerHTML+='<p class="hint">記録がありません。</p>';else box.innerHTML+=`<p>摂取カロリー：${e.food.count.kcal?round(e.food.total.kcal)+' kcal':'未記録'}<br>推定総消費カロリー：${e.total===null?'未算出':round(e.total)+' kcal'}<br>カロリー収支：<b class="${color(e.balance)}">${e.balance===null?'未算出':signed(e.balance)+' kcal'}</b>${e.provisional?'（暫定）':''}<br>体重：${C.numeric(d.weight)?esc(d.weight)+' kg':'未入力'}</p><p class="hint">${esc((d.sessions||[]).flatMap(s=>s.items.map(i=>(i.kind==='cardio'?'🏃 ':'💪 ')+i.name)).join(' / ')||'運動登録なし')}</p>`;box.append(button('この日を編集',()=>{if(changeDate(day))switchTab('record')}))}
function renderHistory(){const root=$('historyList');root.innerHTML='';const dates=Object.keys(store.days).sort().reverse();if(!dates.length){root.innerHTML='<p class="hint">まだ記録がありません。</p>';return}let monthGroup=null,lastMonth='';for(const day of dates){const ym=day.slice(0,7);if(ym!==lastMonth){lastMonth=ym;monthGroup=document.createElement('details');monthGroup.className='history-month';monthGroup.open=ym===dates[0].slice(0,7);const heading=document.createElement('summary');heading.textContent=ym.slice(0,4)+'年'+Number(ym.slice(5))+'月（'+dates.filter(d=>d.startsWith(ym)).length+'日分）';monthGroup.append(heading);root.append(monthGroup)}const d=store.days[day],e=C.energy(store,day),box=document.createElement('details');box.className='history-entry';const summary=document.createElement('summary');summary.innerHTML=`<span><b>${esc(day)}</b> ${marks(d)}${d.restDay?' 🌙':''}</span><span class="history-meta">体重 ${C.numeric(d.weight)?esc(d.weight)+' kg':'未入力'} <b class="${color(e.balance)}">${e.balance===null?'収支未算出':signed(e.balance)+' kcal'}</b></span>`;box.append(summary);const detail=document.createElement('div');detail.className='history-detail';const foods=e.food;detail.innerHTML=`<h3>🍽️ 食事</h3><p>摂取カロリー：<b>${foods.count.kcal?round(foods.total.kcal)+' kcal':'未記録'}</b></p><div class="history-macros">${[['p','P たんぱく質'],['f','F 脂質'],['c','C 炭水化物']].map(([k,label])=>`<div><small>${label}</small><b>${foods.count[k]?round(foods.total[k],1)+' g':'未記録'}</b></div>`).join('')}</div><h3>💪 運動</h3><p>${d.restDay?'🌙 休息日<br>':''}${esc((d.sessions||[]).flatMap(s=>(s.items||[]).map(i=>i.name)).join('、')||'運動登録なし')}</p><p>記録された正味消費：${round(e.exercise.net)} kcal${e.exercise.unresolved?'（未確認の運動あり）':''}</p><p class="hint">${e.provisional?'入力途中のため暫定値です。':''}</p>`;const actions=document.createElement('div');actions.className='actions';actions.append(button('この日を編集',()=>{if(changeDate(day))switchTab('record')}),button('報告コピー',()=>copy(dayReport(day,d))),button('削除',()=>{if(!confirm(day+' の記録を削除しますか？ 削除前コピーを端末内に保存します。'))return;try{localStorage.setItem('chapi-training-before-delete',JSON.stringify(store))}catch(e){notice('削除前コピーを保存できないため中止しました');return}const next=C.clone(store);delete next.days[day];if(persist(next)){if(current===day)chooseDate(day);renderHistory();notice('削除しました。直前コピーはバックアップ書き出しから復旧できます。')}},'danger'));detail.append(actions);box.append(detail);monthGroup.append(box)}}

function renderTemplates(){const root=$('templateList');root.innerHTML='';for(const t of store.templates){const box=document.createElement('div');box.className='template-card';box.innerHTML='<h3>'+esc(t.name)+'</h3><p class="hint">'+t.items.length+'種目 · '+esc(t.items.slice(0,2).map(i=>i.name).join(' / '))+(t.items.length>2?' ほか'+(t.items.length-2)+'種目':'')+'</p>';const actions=document.createElement('div');actions.className='actions';actions.append(button('編集',()=>startEditor(t)),button('複製',()=>{const next=C.clone(store),x=C.clone(t);x.id=uid();x.name+='（コピー）';next.templates.push(x);if(persist(next)){renderTemplates();refreshPickers()}}),button('削除',()=>{if(!confirm('「'+t.name+'」を削除しますか？ 過去の記録は残ります。'))return;const next=C.clone(store);next.templates=next.templates.filter(x=>x.id!==t.id);if(persist(next)){renderTemplates();refreshPickers()}},'danger'));box.append(actions);root.append(box)}}
function startEditor(t){editing=t?C.clone(t):{id:uid(),name:'',items:[]};$('templateName').value=editing.name;$('templateEditor').classList.remove('hidden');renderEditor();$('templateEditor').scrollIntoView({behavior:'smooth',block:'start'})}
function renderEditor(){const root=$('templateItems');root.innerHTML='';editing.items.forEach((it,i)=>{const box=document.createElement('div');box.className='template-item';const row=document.createElement('div');row.className='row';const title=document.createElement('h3');title.textContent=`${i+1}．${it.kind==='cardio'?'有酸素':'筋トレ'}`;row.append(title);const controls=document.createElement('div');controls.className='actions';const up=button('↑',()=>{[editing.items[i-1],editing.items[i]]=[editing.items[i],editing.items[i-1]];renderEditor()});up.disabled=i===0;up.setAttribute('aria-label','種目を上へ');const down=button('↓',()=>{[editing.items[i+1],editing.items[i]]=[editing.items[i],editing.items[i+1]];renderEditor()});down.disabled=i===editing.items.length-1;down.setAttribute('aria-label','種目を下へ');controls.append(up,down,button('削除',()=>{editing.items.splice(i,1);renderEditor()},'danger'));row.append(controls);box.append(row,textInput('種目名',it.name,v=>it.name=v),textInput('名称直下の注釈（任意）',it.annotation,v=>it.annotation=v,true));if(it.kind!=='cardio'){box.append(selectInput('記録方式',it.tracking||'sets',[['sets','セット・重量・回数'],['rounds','周回数（サーキット）']],v=>{it.tracking=v;renderEditor()}));if(it.tracking==='rounds')box.append(numberInput('目安の周回数（周）',it.rounds||2,v=>it.rounds=v,{min:'1',step:'1'}));else{box.append(numberInput('初期セット数',it.sets,v=>it.sets=v,{step:'1',min:'1',max:'30'}))}}else{const l=document.createElement('label');l.className='check';const ck=document.createElement('input');ck.type='checkbox';ck.checked=!!it.noDistance;ck.onchange=()=>it.noDistance=ck.checked;l.append(ck,'距離・歩数欄を表示しない（ステッパー等）');box.append(l)}root.append(box)})}
